import java.io.InputStream;
import java.io.IOException;
import java.util.Arrays;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public int nextInt() {
            int c = readByte();
            while (c <= ' ' && c != -1) {
                c = readByte();
            }
            if (c == -1) return -1;
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = readByte();
            }
            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = readByte();
            }
            return neg ? -res : res;
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        int n = sc.nextInt();
        if (n <= 0) {
            System.out.println(0);
            return;
        }

        int[] x = new int[n + 1];
        int[] y = new int[n + 1];
        x[0] = 0;
        y[0] = 0;

        for (int i = 1; i <= n; i++) {
            x[i] = sc.nextInt();
            y[i] = sc.nextInt();
        }

        int numEdges = n * (n + 1) / 2;
        long[] edges = new long[numEdges];
        int edgeIdx = 0;

        for (int i = 0; i <= n; i++) {
            for (int j = i + 1; j <= n; j++) {
                long dx = x[i] - x[j];
                long dy = y[i] - y[j];
                long distSq = dx * dx + dy * dy;
                // Compactar peso (32 bits), u (12 bits), v (12 bits)
                edges[edgeIdx++] = (distSq << 24) | ((long) i << 12) | j;
            }
        }

        Arrays.sort(edges);

        int[] dp = new int[n + 1];
        int[] maxDp = new int[n + 1];
        int ans = 0;

        int i = 0;
        while (i < numEdges) {
            int j = i;
            long curDist = edges[i] >>> 24;
            while (j < numEdges && (edges[j] >>> 24) == curDist) {
                j++;
            }

            // Primeira passada: calcular as transições para o grupo de mesmo peso
            for (int k = i; k < j; k++) {
                long e = edges[k];
                int u = (int) ((e >>> 12) & 0xFFF);
                int v = (int) (e & 0xFFF);

                if (u == 0) {
                    if (dp[v] + 1 > ans) {
                        ans = dp[v] + 1;
                    }
                } else {
                    int candU = dp[v] + 1;
                    int candV = dp[u] + 1;

                    if (candU > maxDp[u]) {
                        maxDp[u] = candU;
                    }
                    if (candV > maxDp[v]) {
                        maxDp[v] = candV;
                    }
                }
            }

            // Segunda passada: efetivar as atualizações
            for (int k = i; k < j; k++) {
                long e = edges[k];
                int u = (int) ((e >>> 12) & 0xFFF);
                int v = (int) (e & 0xFFF);

                if (u != 0) {
                    if (maxDp[u] > dp[u]) {
                        dp[u] = maxDp[u];
                    }
                    if (maxDp[v] > dp[v]) {
                        dp[v] = maxDp[v];
                    }
                }
            }

            i = j;
        }

        System.out.println(ans);
    }
